using RealmForge.Domain.Entities;
using RealmForge.Shared.Enums;

namespace RealmForge.Infrastructure.Persistence.Seeding.ClassesData;

///	<summary>
///	Warlock (2014 ruleset): class features of the SRD 5.1 (CC BY 4.0) in English; the Italian text is a RealmForge translation
///	that uses the official Italian game terms. Its subclasses have their own files.
///	</summary>
public static class Warlock2014Seeder
{
	public static readonly Guid ClassId = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "class", "warlock");

	public static CharacterClass Build()
	{
		return new CharacterClass
		{
			Id = ClassId,
			Ruleset = RulesetVersion.Dnd5e_2014,
			IsOfficialSRD = true,
			Source = ContentSource.Srd51,
			HitDie = 8,
			PrimaryAbilities = new List<AbilityScore> { AbilityScore.Charisma },
			SavingThrows = new List<AbilityScore> { AbilityScore.Wisdom, AbilityScore.Charisma },
			SkillChoiceCount = 2,
			SkillOptions = new List<Skill> { Skill.Arcana, Skill.Deception, Skill.History, Skill.Intimidation, Skill.Investigation, Skill.Nature, Skill.Religion },
			CasterProgression = CasterProgression.Pact,
			SpellcastingAbility = AbilityScore.Charisma,
			SubclassLevel = 1,
			Translations = new List<CharacterClassTranslation>
			{
				new CharacterClassTranslation
				{
					Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "class", "warlock", "en"),
					Language = LanguageCode.En,
					Name = "Warlock",
					Description = "A spellcaster who gained power through a pact with a mighty otherworldly patron. Warlocks have few spell slots, but they recover them on a short rest, and they shape their gifts with eldritch invocations and a pact boon.",
					SubclassTitle = "Otherworldly Patron",
					ArmorProficiencies = "Light armor",
					WeaponProficiencies = "Simple weapons",
					ToolProficiencies = "None",
					StartingEquipment = "- (a) a light crossbow and 20 bolts or (b) any simple weapon\n- (a) a component pouch or (b) an arcane focus\n- (a) a scholar’s pack or (b) a dungeoneer’s pack\n- Leather armor, any simple weapon, and two daggers",
					ProgressionTable = "| Level | Proficiency Bonus | Features | Cantrips Known | Spells Known | Spell Slots | Slot Level | Invocations Known |\n|---|---|---|---|---|---|---|---|\n| 1st | +2 | Otherworldly Patron, Pact Magic | 2 | 2 | 1 | 1st | — |\n| 2nd | +2 | Eldritch Invocations | 2 | 3 | 2 | 1st | 2 |\n| 3rd | +2 | Pact Boon | 2 | 4 | 2 | 2nd | 2 |\n| 4th | +2 | Ability Score Improvement | 3 | 5 | 2 | 2nd | 3 |\n| 5th | +3 | — | 3 | 6 | 2 | 3rd | 3 |\n| 6th | +3 | Otherworldly Patron feature | 3 | 7 | 2 | 3rd | 4 |\n| 7th | +3 | — | 3 | 8 | 2 | 4th | 4 |\n| 8th | +3 | Ability Score Improvement | 3 | 9 | 2 | 4th | 4 |\n| 9th | +4 | — | 3 | 10 | 2 | 5th | 5 |\n| 10th | +4 | Otherworldly Patron feature | 4 | 10 | 2 | 5th | 5 |\n| 11th | +4 | Mystic Arcanum (6th level) | 4 | 11 | 3 | 5th | 5 |\n| 12th | +4 | Ability Score Improvement | 4 | 11 | 3 | 5th | 6 |\n| 13th | +5 | Mystic Arcanum (7th level) | 4 | 12 | 3 | 5th | 6 |\n| 14th | +5 | Otherworldly Patron feature | 4 | 12 | 3 | 5th | 6 |\n| 15th | +5 | Mystic Arcanum (8th level) | 4 | 13 | 3 | 5th | 7 |\n| 16th | +5 | Ability Score Improvement | 4 | 13 | 3 | 5th | 7 |\n| 17th | +6 | Mystic Arcanum (9th level) | 4 | 14 | 4 | 5th | 7 |\n| 18th | +6 | — | 4 | 14 | 4 | 5th | 8 |\n| 19th | +6 | Ability Score Improvement | 4 | 15 | 4 | 5th | 8 |\n| 20th | +6 | Eldritch Master | 4 | 15 | 4 | 5th | 8 |"
				},
				new CharacterClassTranslation
				{
					Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "class", "warlock", "it"),
					Language = LanguageCode.It,
					Name = "Warlock",
					Description = "Un incantatore che ha ottenuto il proprio potere stringendo un patto con un potente patrono ultraterreno. Il warlock dispone di pochi slot incantesimo, ma li recupera con un riposo breve, e plasma i suoi doni grazie alle suppliche occulte e al dono del patto.",
					SubclassTitle = "Patrono Ultraterreno",
					ArmorProficiencies = "Armature leggere",
					WeaponProficiencies = "Armi semplici",
					ToolProficiencies = "Nessuno",
					StartingEquipment = "- (a) una balestra leggera e 20 quadrelli o (b) un'arma semplice qualsiasi\n- (a) una borsa per componenti o (b) un focus arcano\n- (a) una dotazione da studioso o (b) una dotazione da esploratore di dungeon\n- Un'armatura di cuoio, un'arma semplice qualsiasi e due pugnali",
					ProgressionTable = "| Livello | Bonus di competenza | Privilegi | Trucchetti conosciuti | Incantesimi conosciuti | Slot incantesimo | Livello degli slot | Suppliche conosciute |\n|---|---|---|---|---|---|---|---|\n| 1° | +2 | Patrono Ultraterreno, Magia del Patto | 2 | 2 | 1 | 1° | — |\n| 2° | +2 | Suppliche Occulte | 2 | 3 | 2 | 1° | 2 |\n| 3° | +2 | Dono del Patto | 2 | 4 | 2 | 2° | 2 |\n| 4° | +2 | Aumento dei Punteggi di Caratteristica | 3 | 5 | 2 | 2° | 3 |\n| 5° | +3 | — | 3 | 6 | 2 | 3° | 3 |\n| 6° | +3 | Privilegio del Patrono Ultraterreno | 3 | 7 | 2 | 3° | 4 |\n| 7° | +3 | — | 3 | 8 | 2 | 4° | 4 |\n| 8° | +3 | Aumento dei Punteggi di Caratteristica | 3 | 9 | 2 | 4° | 4 |\n| 9° | +4 | — | 3 | 10 | 2 | 5° | 5 |\n| 10° | +4 | Privilegio del Patrono Ultraterreno | 4 | 10 | 2 | 5° | 5 |\n| 11° | +4 | Arcanum Mistico (6° livello) | 4 | 11 | 3 | 5° | 5 |\n| 12° | +4 | Aumento dei Punteggi di Caratteristica | 4 | 11 | 3 | 5° | 6 |\n| 13° | +5 | Arcanum Mistico (7° livello) | 4 | 12 | 3 | 5° | 6 |\n| 14° | +5 | Privilegio del Patrono Ultraterreno | 4 | 12 | 3 | 5° | 6 |\n| 15° | +5 | Arcanum Mistico (8° livello) | 4 | 13 | 3 | 5° | 7 |\n| 16° | +5 | Aumento dei Punteggi di Caratteristica | 4 | 13 | 3 | 5° | 7 |\n| 17° | +6 | Arcanum Mistico (9° livello) | 4 | 14 | 4 | 5° | 7 |\n| 18° | +6 | — | 4 | 14 | 4 | 5° | 8 |\n| 19° | +6 | Aumento dei Punteggi di Caratteristica | 4 | 15 | 4 | 5° | 8 |\n| 20° | +6 | Maestro dell'Occulto | 4 | 15 | 4 | 5° | 8 |"
				}
			},
			Features = new List<ClassFeature>
			{
				new ClassFeature
				{
					Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "class-feature", "warlock/otherworldly-patron"),
					Ruleset = RulesetVersion.Dnd5e_2014,
					Level = 1,
					SortOrder = 0,
					Translations = new List<ClassFeatureTranslation>
					{
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "class-feature", "warlock/otherworldly-patron", "en"), Language = LanguageCode.En, Name = "Otherworldly Patron", Description = "At 1st level, you have struck a bargain with an otherworldly being, such as the Fiend. Your choice grants you features at 1st level and again at 6th, 10th, and 14th level." },
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "class-feature", "warlock/otherworldly-patron", "it"), Language = LanguageCode.It, Name = "Patrono Ultraterreno", Description = "Al 1° livello il warlock ha stretto un patto con un essere ultraterreno, come l'Immondo. La scelta gli conferisce privilegi al 1° livello e poi al 6°, al 10° e al 14° livello." }
					}
				},
				new ClassFeature
				{
					Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "class-feature", "warlock/pact-magic"),
					Ruleset = RulesetVersion.Dnd5e_2014,
					Level = 1,
					SortOrder = 1,
					Translations = new List<ClassFeatureTranslation>
					{
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "class-feature", "warlock/pact-magic", "en"), Language = LanguageCode.En, Name = "Pact Magic", Description = "Your arcane research and the magic bestowed on you by your patron have given you facility with spells.\n\n**Cantrips.** You know two cantrips of your choice from the warlock spell list. You learn additional warlock cantrips of your choice at higher levels, as shown in the Cantrips Known column of the Warlock table.\n\n**Spell Slots.** The Warlock table shows how many spell slots you have. The table also shows what the level of those slots is; all of your spell slots are the same level. To cast one of your warlock spells of 1st level or higher, you must expend a spell slot. You regain all expended spell slots when you finish a short or long rest.\n\nFor example, when you are 5th level, you have two 3rd-level spell slots. To cast the 1st-level spell *thunderwave*, you must spend one of those slots, and you cast it as a 3rd-level spell.\n\n**Spells Known of 1st Level and Higher.** At 1st level, you know two 1st-level spells of your choice from the warlock spell list.\n\nThe Spells Known column of the Warlock table shows when you learn more warlock spells of your choice of 1st level and higher. A spell you choose must be of a level no higher than what's shown in the table's Slot Level column for your level. When you reach 6th level, for example, you learn a new warlock spell, which can be 1st, 2nd, or 3rd level.\n\nAdditionally, when you gain a level in this class, you can choose one of the warlock spells you know and replace it with another spell from the warlock spell list, which also must be of a level for which you have spell slots.\n\n**Spellcasting Ability.** Charisma is your spellcasting ability for your warlock spells, so you use your Charisma whenever a spell refers to your spellcasting ability. In addition, you use your Charisma modifier when setting the saving throw DC for a warlock spell you cast and when making an attack roll with one.\n\n**Spell save DC** = 8 + your proficiency bonus + your Charisma modifier\n\n**Spell attack modifier** = your proficiency bonus + your Charisma modifier\n\n**Spellcasting Focus.** You can use an arcane focus as a spellcasting focus for your warlock spells." },
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "class-feature", "warlock/pact-magic", "it"), Language = LanguageCode.It, Name = "Magia del Patto", Description = "Le ricerche arcane del warlock e la magia che il suo patrono gli ha conferito gli permettono di padroneggiare gli incantesimi.\n\n**Trucchetti.** Il warlock conosce due trucchetti a sua scelta dalla lista degli incantesimi del warlock. Apprende altri trucchetti da warlock a sua scelta ai livelli superiori, come indicato nella colonna \"Trucchetti conosciuti\" della tabella del Warlock.\n\n**Slot incantesimo.** La tabella del Warlock indica quanti slot incantesimo possiede il warlock e di che livello sono: tutti i suoi slot incantesimo sono dello stesso livello. Per lanciare uno dei suoi incantesimi da warlock di 1° livello o superiore, deve spendere uno slot incantesimo. Recupera tutti gli slot incantesimo spesi quando completa un riposo breve o lungo.\n\nPer esempio, al 5° livello il warlock possiede due slot incantesimo di 3° livello. Per lanciare l'incantesimo di 1° livello *onda tonante* deve spendere uno di quegli slot, e lo lancia come incantesimo di 3° livello.\n\n**Incantesimi conosciuti di 1° livello e superiore.** Al 1° livello il warlock conosce due incantesimi di 1° livello a sua scelta dalla lista degli incantesimi del warlock.\n\nLa colonna \"Incantesimi conosciuti\" della tabella del Warlock indica quando apprende altri incantesimi da warlock di 1° livello o superiore a sua scelta. Un incantesimo scelto non può essere di livello superiore a quello indicato nella colonna \"Livello degli slot\" per il suo livello. Quando arriva al 6° livello, per esempio, apprende un nuovo incantesimo da warlock, che può essere di 1°, 2° o 3° livello.\n\nInoltre, quando ottiene un livello in questa classe, può scegliere uno degli incantesimi da warlock che conosce e sostituirlo con un altro incantesimo della lista del warlock, che deve a sua volta essere di un livello per cui possiede slot incantesimo.\n\n**Caratteristica da incantatore.** Il Carisma è la caratteristica da incantatore per gli incantesimi da warlock, quindi il warlock usa il Carisma ogni volta che un incantesimo fa riferimento alla sua caratteristica da incantatore. Usa inoltre il suo modificatore di Carisma per stabilire la CD dei tiri salvezza degli incantesimi da warlock che lancia e quando effettua un tiro per colpire con uno di essi.\n\n**CD del tiro salvezza degli incantesimi** = 8 + bonus di competenza + modificatore di Carisma\n\n**Modificatore di attacco degli incantesimi** = bonus di competenza + modificatore di Carisma\n\n**Focus da incantatore.** Il warlock può usare un focus arcano come focus da incantatore per i suoi incantesimi da warlock." }
					}
				},
				new ClassFeature
				{
					Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "class-feature", "warlock/eldritch-invocations"),
					Ruleset = RulesetVersion.Dnd5e_2014,
					Level = 2,
					SortOrder = 2,
					Translations = new List<ClassFeatureTranslation>
					{
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "class-feature", "warlock/eldritch-invocations", "en"), Language = LanguageCode.En, Name = "Eldritch Invocations", Description = "In your study of occult lore, you have unearthed eldritch invocations, fragments of forbidden knowledge that imbue you with an abiding magical ability.\n\nAt 2nd level, you gain two eldritch invocations of your choice. When you gain certain warlock levels, you gain additional invocations of your choice, as shown in the Invocations Known column in the class table.\n\nAdditionally, when you gain a level in this class, you can choose one of the invocations you know and replace it with another invocation that you could learn at that level.\n\nIf an eldritch invocation has prerequisites, you must meet them to learn it. You can learn the invocation at the same time that you meet its prerequisites. A level prerequisite refers to your level in this class.\n\n***Agonizing Blast.*** *Prerequisite:* *eldritch blast* cantrip. When you cast *eldritch blast*, add your Charisma modifier to the damage it deals on a hit.\n\n***Armor of Shadows.*** You can cast *mage armor* on yourself at will, without expending a spell slot or material components.\n\n***Ascendant Step.*** *Prerequisite:* 9th level. You can cast *levitate* on yourself at will, without expending a spell slot or material components.\n\n***Beast Speech.*** You can cast *speak with animals* at will, without expending a spell slot.\n\n***Beguiling Influence.*** You gain proficiency in the Deception and Persuasion skills.\n\n***Bewitching Whispers.*** *Prerequisite:* 7th level. You can cast *compulsion* once using a warlock spell slot. You can't do so again until you finish a long rest.\n\n***Book of Ancient Secrets.*** *Prerequisite:* Pact of the Tome feature. You can now inscribe magical rituals in your Book of Shadows. Choose two 1st-level spells that have the ritual tag from any class's spell list (the two needn't be from the same list). The spells appear in the book and don't count against the number of spells you know. With your Book of Shadows in hand, you can cast the chosen spells as rituals. You can't cast the spells except as rituals, unless you've learned them by some other means. You can also cast a warlock spell you know as a ritual if it has the ritual tag.\n\nOn your adventures, you can add other ritual spells to your Book of Shadows. When you find such a spell, you can add it to the book if the spell's level is equal to or less than half your warlock level (rounded up) and if you can spare the time to transcribe the spell. For each level of the spell, the transcription process takes 2 hours and costs 50 gp for the rare inks needed to inscribe it.\n\n***Chains of Carceri.*** *Prerequisite:* 15th level, Pact of the Chain feature. You can cast *hold monster* at will, targeting a celestial, fiend, or elemental, without expending a spell slot or material components. You must finish a long rest before you can use this invocation on the same creature again.\n\n***Devil's Sight.*** You can see normally in darkness, both magical and nonmagical, to a distance of 120 feet.\n\n***Dreadful Word.*** *Prerequisite:* 7th level. You can cast *confusion* once using a warlock spell slot. You can't do so again until you finish a long rest.\n\n***Eldritch Sight.*** You can cast *detect magic* at will, without expending a spell slot.\n\n***Eldritch Spear.*** *Prerequisite:* *eldritch blast* cantrip. When you cast *eldritch blast*, its range is 300 feet.\n\n***Eyes of the Rune Keeper.*** You can read all writing.\n\n***Fiendish Vigor.*** You can cast *false life* on yourself at will as a 1st-level spell, without expending a spell slot or material components.\n\n***Gaze of Two Minds.*** You can use your action to touch a willing humanoid and perceive through its senses until the end of your next turn. As long as the creature is on the same plane of existence as you, you can use your action on subsequent turns to maintain this connection, extending the duration until the end of your next turn. While perceiving through the other creature's senses, you benefit from any special senses possessed by that creature, and you are blinded and deafened to your own surroundings.\n\n***Lifedrinker.*** *Prerequisite:* 12th level, Pact of the Blade feature. When you hit a creature with your pact weapon, the creature takes extra necrotic damage equal to your Charisma modifier (minimum 1).\n\n***Mask of Many Faces.*** You can cast *disguise self* at will, without expending a spell slot.\n\n***Master of Myriad Forms.*** *Prerequisite:* 15th level. You can cast *alter self* at will, without expending a spell slot.\n\n***Minions of Chaos.*** *Prerequisite:* 9th level. You can cast *conjure elemental* once using a warlock spell slot. You can't do so again until you finish a long rest.\n\n***Mire the Mind.*** *Prerequisite:* 5th level. You can cast *slow* once using a warlock spell slot. You can't do so again until you finish a long rest.\n\n***Misty Visions.*** You can cast *silent image* at will, without expending a spell slot or material components.\n\n***One With Shadows.*** *Prerequisite:* 5th level. When you are in an area of dim light or darkness, you can use your action to become invisible until you move or take an action or a reaction.\n\n***Otherworldly Leap.*** *Prerequisite:* 9th level. You can cast *jump* on yourself at will, without expending a spell slot or material components.\n\n***Repelling Blast.*** *Prerequisite:* *eldritch blast* cantrip. When you hit a creature with *eldritch blast*, you can push the creature up to 10 feet away from you in a straight line.\n\n***Sculptor of Flesh.*** *Prerequisite:* 7th level. You can cast *polymorph* once using a warlock spell slot. You can't do so again until you finish a long rest.\n\n***Sign of Ill Omen.*** *Prerequisite:* 5th level. You can cast *bestow curse* once using a warlock spell slot. You can't do so again until you finish a long rest.\n\n***Thief of Five Fates.*** You can cast *bane* once using a warlock spell slot. You can't do so again until you finish a long rest.\n\n***Thirsting Blade.*** *Prerequisite:* 5th level, Pact of the Blade feature. You can attack with your pact weapon twice, instead of once, whenever you take the Attack action on your turn.\n\n***Visions of Distant Realms.*** *Prerequisite:* 15th level. You can cast *arcane eye* at will, without expending a spell slot.\n\n***Voice of the Chain Master.*** *Prerequisite:* Pact of the Chain feature. You can communicate telepathically with your familiar and perceive through your familiar's senses as long as you are on the same plane of existence. Additionally, while perceiving through your familiar's senses, you can also speak through your familiar in your own voice, even if your familiar is normally incapable of speech.\n\n***Whispers of the Grave.*** *Prerequisite:* 9th level. You can cast *speak with dead* at will, without expending a spell slot.\n\n***Witch Sight.*** *Prerequisite:* 15th level. You can see the true form of any shapechanger or creature concealed by illusion or transmutation magic while the creature is within 30 feet of you and within line of sight." },
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "class-feature", "warlock/eldritch-invocations", "it"), Language = LanguageCode.It, Name = "Suppliche Occulte", Description = "Studiando le scienze occulte, il warlock ha scoperto le suppliche occulte, frammenti di conoscenze proibite che gli conferiscono una capacità magica permanente.\n\nAl 2° livello il warlock ottiene due suppliche occulte a sua scelta. A determinati livelli da warlock ottiene altre suppliche a sua scelta, come indicato nella colonna \"Suppliche conosciute\" della tabella della classe.\n\nInoltre, quando ottiene un livello in questa classe, può scegliere una delle suppliche che conosce e sostituirla con un'altra che potrebbe apprendere a quel livello.\n\nSe una supplica occulta ha dei prerequisiti, il warlock deve soddisfarli per apprenderla. Può apprendere la supplica nel momento stesso in cui soddisfa i prerequisiti. Un prerequisito di livello si riferisce al suo livello in questa classe.\n\n***Deflagrazione Agonizzante.*** *Prerequisito:* trucchetto *deflagrazione occulta*. Quando lancia *deflagrazione occulta*, il warlock aggiunge il suo modificatore di Carisma ai danni che infligge quando colpisce.\n\n***Armatura delle Ombre.*** Il warlock può lanciare *armatura magica* su se stesso a volontà, senza spendere uno slot incantesimo o componenti materiali.\n\n***Passo Ascendente.*** *Prerequisito:* 9° livello. Il warlock può lanciare *levitazione* su se stesso a volontà, senza spendere uno slot incantesimo o componenti materiali.\n\n***Lingue delle Bestie.*** Il warlock può lanciare *parlare con gli animali* a volontà, senza spendere uno slot incantesimo.\n\n***Influenza Seducente.*** Il warlock ottiene competenza nelle abilità Inganno e Persuasione.\n\n***Sussurri Stregati.*** *Prerequisito:* 7° livello. Il warlock può lanciare *compulsione* una volta usando uno slot incantesimo da warlock. Non può farlo di nuovo finché non completa un riposo lungo.\n\n***Libro degli Antichi Segreti.*** *Prerequisito:* privilegio Patto del Tomo. Il warlock può ora trascrivere rituali magici nel suo Libro delle Ombre. Sceglie due incantesimi di 1° livello con la caratteristica rituale dalla lista degli incantesimi di qualsiasi classe (non devono provenire necessariamente dalla stessa lista). Gli incantesimi compaiono nel libro e non contano ai fini del numero di incantesimi conosciuti. Tenendo in mano il Libro delle Ombre, il warlock può lanciare gli incantesimi scelti come rituali. Non può lanciarli se non come rituali, a meno che non li abbia appresi in altro modo. Può inoltre lanciare come rituale un incantesimo da warlock che conosce, se ha la caratteristica rituale.\n\nDurante le sue avventure, il warlock può aggiungere altri incantesimi rituali al Libro delle Ombre. Quando trova un incantesimo del genere, può aggiungerlo al libro se il livello dell'incantesimo è pari o inferiore alla metà del suo livello da warlock (arrotondata per eccesso) e se ha il tempo di trascriverlo. Per ogni livello dell'incantesimo, la trascrizione richiede 2 ore e costa 50 mo per gli inchiostri rari necessari.\n\n***Catene di Carceri.*** *Prerequisito:* 15° livello, privilegio Patto della Catena. Il warlock può lanciare *blocca mostri* a volontà, prendendo come bersaglio un celestiale, un immondo o un elementale, senza spendere uno slot incantesimo o componenti materiali. Deve completare un riposo lungo prima di poter usare di nuovo questa supplica sulla stessa creatura.\n\n***Vista del Diavolo.*** Il warlock vede normalmente nell'oscurità, sia magica che non magica, fino a una distanza di 36 metri.\n\n***Parola Temibile.*** *Prerequisito:* 7° livello. Il warlock può lanciare *confusione* una volta usando uno slot incantesimo da warlock. Non può farlo di nuovo finché non completa un riposo lungo.\n\n***Vista dell'Occulto.*** Il warlock può lanciare *individuazione del magico* a volontà, senza spendere uno slot incantesimo.\n\n***Lancia Occulta.*** *Prerequisito:* trucchetto *deflagrazione occulta*. Quando il warlock lancia *deflagrazione occulta*, la sua gittata è di 90 metri.\n\n***Occhi del Custode delle Rune.*** Il warlock è in grado di leggere qualsiasi scritto.\n\n***Vigore Immondo.*** Il warlock può lanciare *vita falsata* su se stesso a volontà come incantesimo di 1° livello, senza spendere uno slot incantesimo o componenti materiali.\n\n***Sguardo delle Due Menti.*** Il warlock può usare la sua azione per toccare un umanoide consenziente e percepire attraverso i suoi sensi fino alla fine del suo turno successivo. Finché la creatura si trova sul suo stesso piano di esistenza, nei turni successivi il warlock può usare la sua azione per mantenere il collegamento, estendendone la durata fino alla fine del suo turno successivo. Mentre percepisce attraverso i sensi dell'altra creatura, beneficia di qualsiasi senso speciale posseduto da quella creatura ed è accecato e assordato per quanto riguarda ciò che lo circonda.\n\n***Succhiavita.*** *Prerequisito:* 12° livello, privilegio Patto della Lama. Quando il warlock colpisce una creatura con la sua arma del patto, la creatura subisce danni necrotici extra pari al modificatore di Carisma del warlock (minimo 1).\n\n***Maschera dei Molti Volti.*** Il warlock può lanciare *camuffare se stesso* a volontà, senza spendere uno slot incantesimo.\n\n***Maestro di Mille Forme.*** *Prerequisito:* 15° livello. Il warlock può lanciare *alterare se stesso* a volontà, senza spendere uno slot incantesimo.\n\n***Servitori del Caos.*** *Prerequisito:* 9° livello. Il warlock può lanciare *evoca elementale* una volta usando uno slot incantesimo da warlock. Non può farlo di nuovo finché non completa un riposo lungo.\n\n***Fardello Mentale.*** *Prerequisito:* 5° livello. Il warlock può lanciare *lentezza* una volta usando uno slot incantesimo da warlock. Non può farlo di nuovo finché non completa un riposo lungo.\n\n***Visioni Velate.*** Il warlock può lanciare *immagine silenziosa* a volontà, senza spendere uno slot incantesimo o componenti materiali.\n\n***Tutt'uno con le Ombre.*** *Prerequisito:* 5° livello. Quando si trova in un'area di luce fioca o di oscurità, il warlock può usare la sua azione per diventare invisibile finché non si muove o non effettua un'azione o una reazione.\n\n***Balzo Ultraterreno.*** *Prerequisito:* 9° livello. Il warlock può lanciare *saltare* su se stesso a volontà, senza spendere uno slot incantesimo o componenti materiali.\n\n***Deflagrazione Respingente.*** *Prerequisito:* trucchetto *deflagrazione occulta*. Quando il warlock colpisce una creatura con *deflagrazione occulta*, può spingerla in linea retta fino a 3 metri lontano da sé.\n\n***Scultore della Carne.*** *Prerequisito:* 7° livello. Il warlock può lanciare *metamorfosi* una volta usando uno slot incantesimo da warlock. Non può farlo di nuovo finché non completa un riposo lungo.\n\n***Presagio di Sventura.*** *Prerequisito:* 5° livello. Il warlock può lanciare *scagliare maledizione* una volta usando uno slot incantesimo da warlock. Non può farlo di nuovo finché non completa un riposo lungo.\n\n***Ladro dei Cinque Fati.*** Il warlock può lanciare *anatema* una volta usando uno slot incantesimo da warlock. Non può farlo di nuovo finché non completa un riposo lungo.\n\n***Lama Assetata.*** *Prerequisito:* 5° livello, privilegio Patto della Lama. Il warlock può attaccare due volte con la sua arma del patto, anziché una, ogni volta che effettua l'azione di Attacco nel suo turno.\n\n***Visione dei Reami Lontani.*** *Prerequisito:* 15° livello. Il warlock può lanciare *occhio arcano* a volontà, senza spendere uno slot incantesimo.\n\n***Voce del Signore delle Catene.*** *Prerequisito:* privilegio Patto della Catena. Il warlock può comunicare telepaticamente con il suo famiglio e percepire attraverso i suoi sensi finché si trovano sullo stesso piano di esistenza. Inoltre, mentre percepisce attraverso i sensi del famiglio, può anche parlare attraverso di esso con la propria voce, anche se normalmente il famiglio non è in grado di parlare.\n\n***Sussurri dalla Tomba.*** *Prerequisito:* 9° livello. Il warlock può lanciare *parlare con i morti* a volontà, senza spendere uno slot incantesimo.\n\n***Vista Stregata.*** *Prerequisito:* 15° livello. Il warlock vede la vera forma di qualsiasi mutaforma o creatura celata da magia di illusione o di trasmutazione, se la creatura si trova entro 9 metri da lui e in linea di vista." }
					}
				},
				new ClassFeature
				{
					Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "class-feature", "warlock/pact-boon"),
					Ruleset = RulesetVersion.Dnd5e_2014,
					Level = 3,
					SortOrder = 3,
					Translations = new List<ClassFeatureTranslation>
					{
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "class-feature", "warlock/pact-boon", "en"), Language = LanguageCode.En, Name = "Pact Boon", Description = "At 3rd level, your otherworldly patron bestows a gift upon you for your loyal service. You gain one of the following features of your choice.\n\n***Pact of the Blade.*** You can use your action to create a pact weapon in your empty hand. You can choose the form that this melee weapon takes each time you create it. You are proficient with it while you wield it. This weapon counts as magical for the purpose of overcoming resistance and immunity to nonmagical attacks and damage.\n\nYour pact weapon disappears if it is more than 5 feet away from you for 1 minute or more. It also disappears if you use this feature again, if you dismiss the weapon (no action required), or if you die.\n\nYou can transform one magic weapon into your pact weapon by performing a special ritual while you hold the weapon. You perform the ritual over the course of 1 hour, which can be done during a short rest. You can then dismiss the weapon, shunting it into an extradimensional space, and it appears whenever you create your pact weapon thereafter. You can't affect an artifact or a sentient weapon in this way. The weapon ceases being your pact weapon if you die, if you perform the 1-hour ritual on a different weapon, or if you use a 1-hour ritual to break your bond to it. The weapon appears at your feet if it is in the extradimensional space when the bond breaks.\n\n***Pact of the Chain.*** You learn the *find familiar* spell and can cast it as a ritual. The spell doesn't count against your number of spells known. When you cast the spell, you can choose one of the normal forms for your familiar or one of the following special forms: imp, pseudodragon, quasit, or sprite.\n\nAdditionally, when you take the Attack action, you can forgo one of your own attacks to allow your familiar to make one attack of its own with its reaction.\n\n***Pact of the Tome.*** Your patron gives you a grimoire called a Book of Shadows. When you gain this feature, choose three cantrips from any class's spell list (the three needn't be from the same list). While the book is on your person, you can cast those cantrips at will. They don't count against your number of cantrips known. If they don't appear on the warlock spell list, they are nonetheless warlock spells for you.\n\nIf you lose your Book of Shadows, you can perform a 1-hour ceremony to receive a replacement from your patron. This ceremony can be performed during a short or long rest, and it destroys the previous book. The book turns to ash when you die." },
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "class-feature", "warlock/pact-boon", "it"), Language = LanguageCode.It, Name = "Dono del Patto", Description = "Al 3° livello il patrono ultraterreno ricompensa il warlock per i suoi fedeli servigi con un dono. Il warlock ottiene uno dei seguenti privilegi a sua scelta.\n\n***Patto della Lama.*** Il warlock può usare la sua azione per creare un'arma del patto nella sua mano libera. Può scegliere la forma di quest'arma da mischia ogni volta che la crea, e ha competenza in essa finché la impugna. L'arma è considerata magica al fine di superare la resistenza e l'immunità agli attacchi e ai danni non magici.\n\nL'arma del patto scompare se rimane a più di 1,5 metri dal warlock per 1 minuto o più. Scompare anche se il warlock usa di nuovo questo privilegio, se la congeda (non è richiesta alcuna azione) o se muore.\n\nIl warlock può trasformare un'arma magica nella sua arma del patto celebrando un rituale speciale mentre la impugna. Il rituale dura 1 ora e può essere svolto durante un riposo breve. In seguito può congedare l'arma, relegandola in uno spazio extradimensionale, e l'arma ricompare ogni volta che crea la sua arma del patto. Non è possibile influenzare in questo modo un artefatto o un'arma senziente. L'arma cessa di essere l'arma del patto se il warlock muore, se svolge il rituale di 1 ora su un'altra arma o se usa un rituale di 1 ora per spezzare il legame. Se l'arma si trova nello spazio extradimensionale quando il legame si spezza, compare ai piedi del warlock.\n\n***Patto della Catena.*** Il warlock apprende l'incantesimo *trova famiglio* e può lanciarlo come rituale. L'incantesimo non conta ai fini del numero di incantesimi conosciuti. Quando lancia l'incantesimo, può scegliere per il suo famiglio una delle forme normali oppure una delle seguenti forme speciali: imp, pseudodrago, quasit o spiritello.\n\nInoltre, quando effettua l'azione di Attacco, il warlock può rinunciare a uno dei suoi attacchi per permettere al suo famiglio di effettuare un attacco usando la propria reazione.\n\n***Patto del Tomo.*** Il patrono dona al warlock un grimorio chiamato Libro delle Ombre. Quando ottiene questo privilegio, il warlock sceglie tre trucchetti dalla lista degli incantesimi di qualsiasi classe (non devono provenire necessariamente dalla stessa lista). Finché ha il libro con sé, può lanciare quei trucchetti a volontà. Non contano ai fini del numero di trucchetti conosciuti e, anche se non compaiono nella lista del warlock, per lui sono comunque incantesimi da warlock.\n\nSe perde il Libro delle Ombre, il warlock può svolgere una cerimonia di 1 ora per riceverne uno nuovo dal suo patrono. La cerimonia può essere svolta durante un riposo breve o lungo e distrugge il libro precedente. Il libro si riduce in cenere quando il warlock muore." }
					}
				},
				new ClassFeature
				{
					Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "class-feature", "warlock/ability-score-improvement"),
					Ruleset = RulesetVersion.Dnd5e_2014,
					Level = 4,
					SortOrder = 4,
					Translations = new List<ClassFeatureTranslation>
					{
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "class-feature", "warlock/ability-score-improvement", "en"), Language = LanguageCode.En, Name = "Ability Score Improvement", Description = "When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can't increase an ability score above 20 using this feature." },
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "class-feature", "warlock/ability-score-improvement", "it"), Language = LanguageCode.It, Name = "Aumento dei Punteggi di Caratteristica", Description = "Quando arriva al 4° livello, e poi all'8°, al 12°, al 16° e al 19° livello, il personaggio può aumentare di 2 un punteggio di caratteristica a sua scelta, oppure aumentare di 1 due punteggi di caratteristica a sua scelta. Come di consueto, questo privilegio non consente di aumentare un punteggio di caratteristica oltre 20." }
					}
				},
				new ClassFeature
				{
					Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "class-feature", "warlock/mystic-arcanum"),
					Ruleset = RulesetVersion.Dnd5e_2014,
					Level = 11,
					SortOrder = 5,
					Translations = new List<ClassFeatureTranslation>
					{
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "class-feature", "warlock/mystic-arcanum", "en"), Language = LanguageCode.En, Name = "Mystic Arcanum", Description = "At 11th level, your patron bestows upon you a magical secret called an arcanum. Choose one 6th-level spell from the warlock spell list as this arcanum.\n\nYou can cast your arcanum spell once without expending a spell slot. You must finish a long rest before you can do so again.\n\nAt higher levels, you gain more warlock spells of your choice that can be cast in this way: one 7th-level spell at 13th level, one 8th-level spell at 15th level, and one 9th-level spell at 17th level. You regain all uses of your Mystic Arcanum when you finish a long rest." },
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "class-feature", "warlock/mystic-arcanum", "it"), Language = LanguageCode.It, Name = "Arcanum Mistico", Description = "All'11° livello il patrono rivela al warlock un segreto magico chiamato arcanum. Il warlock sceglie come arcanum un incantesimo di 6° livello dalla lista degli incantesimi del warlock.\n\nPuò lanciare il suo incantesimo arcanum una volta senza spendere uno slot incantesimo, e deve completare un riposo lungo prima di poterlo fare di nuovo.\n\nAi livelli superiori ottiene altri incantesimi da warlock a sua scelta che possono essere lanciati in questo modo: un incantesimo di 7° livello al 13° livello, uno di 8° livello al 15° livello e uno di 9° livello al 17° livello. Recupera tutti gli utilizzi del suo Arcanum Mistico quando completa un riposo lungo." }
					}
				},
				new ClassFeature
				{
					Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "class-feature", "warlock/eldritch-master"),
					Ruleset = RulesetVersion.Dnd5e_2014,
					Level = 20,
					SortOrder = 6,
					Translations = new List<ClassFeatureTranslation>
					{
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "class-feature", "warlock/eldritch-master", "en"), Language = LanguageCode.En, Name = "Eldritch Master", Description = "At 20th level, you can draw on your inner reserve of mystical power while entreating your patron to regain expended spell slots. You can spend 1 minute entreating your patron for aid to regain all your expended spell slots from your Pact Magic feature. Once you regain spell slots with this feature, you must finish a long rest before you can do so again." },
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "class-feature", "warlock/eldritch-master", "it"), Language = LanguageCode.It, Name = "Maestro dell'Occulto", Description = "Al 20° livello il warlock può attingere alla sua riserva interiore di potere mistico implorando il suo patrono di restituirgli gli slot incantesimo spesi. Può passare 1 minuto a implorare l'aiuto del patrono per recuperare tutti gli slot incantesimo spesi del suo privilegio Magia del Patto. Una volta recuperati gli slot incantesimo con questo privilegio, deve completare un riposo lungo prima di poterlo fare di nuovo." }
					}
				}
			}
		};
	}
}
